cards.solution:
class Pelanggan {}
class Member extends Pelanggan {}
class Vip extends Member {}
function hargaAkhir(pelanggan, harga) {
  if (pelanggan instanceof Vip) return harga * 80 / 100;
  if (pelanggan instanceof Member) return harga * 90 / 100;
  return harga;
}
console.log(hargaAkhir(new Pelanggan(), 100000));
console.log(hargaAkhir(new Member(), 100000));
console.log(hargaAkhir(new Vip(), 100000));
